#include <stdio.h>
#include <stdlib.h>
struct Node {
int data;
struct Node *next;};
// Função para adicionar um nó ao 
início
void push(struct Node **head, int
new_data) {
struct Node *new_node = (struct
Node *)malloc(sizeof(struct Node));
new_node->data = new_data;
new_node->next = *head;
*head = new_node;}
// Função para imprimir a lista
void printList(struct Node *node) {
while (node != NULL) {
printf("%d -> ", node->data);
node = node->next;
}
printf("NULL\n");}
int main() {
struct Node *head = NULL;
push(&head, 10);
push(&head, 20);
push(&head, 30);
printList(head);
return 0;
}

